% IDEAS Report 3
function [fwhm_pixels, fwhm_um] = calculate_fwhm_group8(csv_filepath, conversion_factor, step_size)
    % Default step size to 0.001 as specified in the slides if omitted
    if nargin < 3
        step_size = 0.001; 
    end

    % 1. Import data from CSV generated by ImageJ
    % Columns: x = Distance (pixels), y = Intensity / Gray Value
    data = readmatrix(csv_filepath);
    x = data(:, 1);
    y = data(:, 2);

    % 2. Define fine evaluation grid (xnew) from 0 to max pixel value
    xnew = 0:step_size:max(x);

    % 3. Interpolate using Piecewise Cubic Hermite Interpolating Polynomial ('pchip')
    ynew = interp1(x, y, xnew, 'pchip');

    % 4. Compute the Half-Maximum threshold value
    halfmax = 0.5 * (max(ynew) - min(ynew)) + min(ynew);

    % 5. Create binary mask array where ynew > halfmax
    ybin = ynew > halfmax;

    % 6. Plot the interpolated curve and binary threshold overlay
    figure;
    plot(xnew, ynew, 'b-', 'LineWidth', 1.5); hold on;
    plot(xnew, ybin .* halfmax, 'r-', 'LineWidth', 2);
    title(['Interpolated Data Plot for ', strrep(csv_filepath, '_', '\_')]);
    xlabel('Distance (Pixels)');
    ylabel('Gray Value');
    legend('Interpolated Curve', 'Half-Max Binary Threshold');
    grid on;
    hold off;

    % 7. Calculate FWHM in pixels using the sum of logical TRUE points in ybin
    % Summing elements over fine step grid gives the total width in pixels
    fwhm_pixels = sum(ybin) * step_size;

    % 8. Convert distance values from pixels to micrometers (µm)
    fwhm_um = fwhm_pixels * conversion_factor;
end